#' Group CFA (Invariance)
#'
#' Tests the measurement invariance of a one-factor or correlated-factors 
#' model across groups. Fits the model under increasingly strict equality 
#' constraints (configural, [thresholds,] loadings, intercepts and optionally 
#' residual variances), compares each step with the previous one and points at 
#' the constraints that fit worst.
#' 
#'
#' @examples
#' \donttest{
#' data('wizdata', package = 'psyWiz')
#' psyWiz::groupCfa(wizdata, group = 'country', run = TRUE, factors = list(
#'     list(label = 'Trust', vars = c('trust1', 'trust2', 'trust3', 'trust4')),
#'     list(label = 'Stress', vars = c('stress1', 'stress2', 'stress3', 'stress4'))))
#'}
#' @param data the data as a data frame
#' @param factors a list of lists, each with a \code{label} (the factor name)
#'   and \code{vars} (the names of its items)
#' @param group a string naming the grouping variable
#' @param run \code{TRUE} or \code{FALSE} (default), fit the models; while
#'   \code{FALSE} only a summary of the plan is shown
#' @param type \code{'auto'} (default; ordinal variables are treated as
#'   ordinal, continuous ones as continuous), \code{'ordinal'} or
#'   \code{'continuous'}
#' @param estimator \code{'auto'} (default; MLR for continuous items, WLSMV
#'   for ordinal items), \code{'ML'}, \code{'MLR'}, \code{'MLM'},
#'   \code{'WLSMV'}, \code{'ULSMV'}, \code{'DWLS'} or \code{'ULS'}
#' @param missing \code{'auto'} (default; FIML for ML and MLR, pairwise
#'   deletion for ordinal items), \code{'listwise'}, \code{'fiml'} or
#'   \code{'pairwise'}
#' @param strict \code{TRUE} or \code{FALSE} (default), add a step
#'   constraining the residual variances to equality
#' @param parallel \code{TRUE} (default) or \code{FALSE}, fit the models
#'   concurrently when one takes more than a second
#' @param useCfi \code{TRUE} (default) or \code{FALSE}, use the change in CFI
#'   for the verdict
#' @param cutCfi a number (default 0.010), the largest acceptable drop in CFI
#' @param useRmsea \code{TRUE} (default) or \code{FALSE}, use the change in
#'   RMSEA for the verdict
#' @param cutRmsea a number (default 0.015), the largest acceptable rise in
#'   RMSEA
#' @param useSrmr \code{TRUE} or \code{FALSE} (default), use the change in
#'   SRMR for the verdict
#' @param cutSrmrLoad a number (default 0.030), the largest acceptable rise in
#'   SRMR at the step that constrains loadings
#' @param cutSrmr a number (default 0.010), the largest acceptable rise in
#'   SRMR at the other steps
#' @param useChisq \code{TRUE} or \code{FALSE} (default), use the chi-square
#'   difference test for the verdict
#' @param alpha a number (default 0.05), the significance level of the
#'   difference test
#' @param culprits \code{'failed'} (default), \code{'all'} or \code{'none'}:
#'   for which steps to list the score tests of the constraints
#' @param culpritsN an integer (default 5), how many constraints to list for
#'   each step
#' @param showLoadings \code{TRUE} or \code{FALSE} (default), show the
#'   standardized loadings of the configural model for each group
#' @param partial \code{TRUE} or \code{FALSE} (default), refit the ladder
#'   releasing, item by item, the constraints with the largest score tests at
#'   every step that is not supported
#' @param maxFree an integer (default 2), the largest number of items released
#'   per factor at one step
#' @param showComb \code{TRUE} or \code{FALSE} (default), draw the comb plot:
#'   one tooth per item, whose length is the variance the item shares with its
#'   factor
#' @param combThick \code{TRUE} or \code{FALSE} (default), make each tooth as
#'   thick as the item's observed variance is large
#' @param showPath \code{TRUE} or \code{FALSE} (default), draw the path
#'   diagram
#' @param pathNumbers \code{TRUE} (default) or \code{FALSE}, print the
#'   standardized loadings on the arrows
#' @param pathWidth \code{TRUE} (default) or \code{FALSE}, make the width of
#'   an arrow proportional to its loading
#' @param highlight \code{TRUE} or \code{FALSE} (default), show flagged
#'   changes in fit in red
#' @param robust \code{TRUE} or \code{FALSE} (default), refit the ladder under
#'   other estimators and item treatments, apply five decision rules to each
#'   step and report how often each level of invariance is supported (takes
#'   about four times as long)
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$groups} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$fit} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$comparison} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$culprits} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$partialLadder} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$partialReleased} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$robustSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$robustGrid} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$loadings} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$comb} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$pathFig} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$groups$asDF}
#'
#' \code{as.data.frame(results$groups)}
#'
#' @export
groupCfa <- function(
    data,
    factors = list(
                list(label="Factor 1", vars=list())),
    group,
    run = FALSE,
    type = "auto",
    estimator = "auto",
    missing = "auto",
    strict = FALSE,
    parallel = TRUE,
    useCfi = TRUE,
    cutCfi = 0.01,
    useRmsea = TRUE,
    cutRmsea = 0.015,
    useSrmr = FALSE,
    cutSrmrLoad = 0.03,
    cutSrmr = 0.01,
    useChisq = FALSE,
    alpha = 0.05,
    culprits = "failed",
    culpritsN = 5,
    showLoadings = FALSE,
    partial = FALSE,
    maxFree = 2,
    showComb = FALSE,
    combThick = FALSE,
    showPath = FALSE,
    pathNumbers = TRUE,
    pathWidth = TRUE,
    highlight = FALSE,
    robust = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("groupCfa requires jmvcore to be installed (restart may be required)")

    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(group), group, NULL))

    for (v in group) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- groupCfaOptions$new(
        factors = factors,
        group = group,
        run = run,
        type = type,
        estimator = estimator,
        missing = missing,
        strict = strict,
        parallel = parallel,
        useCfi = useCfi,
        cutCfi = cutCfi,
        useRmsea = useRmsea,
        cutRmsea = cutRmsea,
        useSrmr = useSrmr,
        cutSrmrLoad = cutSrmrLoad,
        cutSrmr = cutSrmr,
        useChisq = useChisq,
        alpha = alpha,
        culprits = culprits,
        culpritsN = culpritsN,
        showLoadings = showLoadings,
        partial = partial,
        maxFree = maxFree,
        showComb = showComb,
        combThick = combThick,
        showPath = showPath,
        pathNumbers = pathNumbers,
        pathWidth = pathWidth,
        highlight = highlight,
        robust = robust)

    analysis <- groupCfaClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

